mysqldump -u root -p db_school > D:/bak/school.sql
mysql -u root -p
USE db_school;
SOURCE D:/bak/school.sql
SELECT * FROM student WHERE sdept = '计算机'
  INTO OUTFILE 'D:/bak/cs.txt'
  FIELDS TERMINATED BY ',';
CREATE TABLE stu_cs LIKE student;
LOAD DATA INFILE 'D:/bak/cs.txt'
  INTO TABLE stu_cs
  FIELDS TERMINATED BY ',';
